const p=JSON.parse(document.querySelector('#planner-data').textContent);function run(){const workload=Number(document.querySelector('#workload').value),throughput=Number(document.querySelector('#throughput').value),streams=Number(document.querySelector('#streams').value),buffer=Number(document.querySelector('#buffer').value),adjusted=Math.round(workload*(1+buffer/100)*100)/100,capacity=Math.round(throughput*streams*100)/100,days=Math.ceil(adjusted/capacity);document.querySelector('#adjusted').textContent=adjusted.toFixed(2);document.querySelector('#capacity').textContent=capacity.toFixed(2);document.querySelector('#days').textContent=String(days);document.querySelector('#band').textContent=days<=2?'QUICK':days<=5?'STANDARD':'EXTENDED'}document.querySelector('#calculate-capacity').addEventListener('click',run);run();
